### Last Known Working Electron version

Unknown

### Expected Behavior

Calling `desktopCapturer.getSources()` should not cause a subsequent non-interactive macOS `/usr/sbin/screencapture -D 1` call from the same Electron main process to fail when Screen Recording permission is granted.

### Actual Behavior

On a Mac with three displays and Screen Recording permission granted, an immediate `screencapture -D 1` call after `desktopCapturer.getSources()` can fail with:

```text
could not create image from display
```

The same command succeeds outside Electron, and it also succeeds from Electron if run before `desktopCapturer.getSources()` or after a short delay. `systemPreferences.getMediaAccessStatus('screen')` reports `granted`.

In the affected app, this happens when `desktopCapturer` returns an empty thumbnail for a screen source and we attempt to fall back to `screencapture`; the fallback can then fail on the primary display because it runs immediately after `desktopCapturer.getSources()`.

### Testcase Gist URL

_No response_

### Additional Information

Minimal main-process repro:

```js
const { app, desktopCapturer, nativeImage, systemPreferences } = require('electron');
const { execFile } = require('node:child_process');
const fs = require('node:fs/promises');
const os = require('node:os');
const path = require('node:path');
const { promisify } = require('node:util');
const execFileAsync = promisify(execFile);

async function cap(label) {
  const p = path.join(os.tmpdir(), `electron-screencapture-${process.pid}-${label}.png`);
  try {
    await execFileAsync('/usr/sbin/screencapture', ['-x', '-t', 'png', '-D', '1', p], {
      timeout: 10000,
      maxBuffer: 1000000,
    });
    const buf = await fs.readFile(p);
    return { label, ok: true, bytes: buf.length, size: nativeImage.createFromBuffer(buf).getSize() };
  } catch (e) {
    return { label, ok: false, message: e.message, stderr: e.stderr };
  } finally {
    await fs.rm(p, { force: true }).catch(() => {});
  }
}

app.whenReady().then(async () => {
  const results = [];
  results.push({ media: systemPreferences.getMediaAccessStatus('screen') });
  results.push(await cap('before'));

  const sources = await desktopCapturer.getSources({
    types: ['screen', 'window'],
    thumbnailSize: { width: 1920, height: 1080 },
    fetchWindowIcons: false,
  });
  results.push({
    screens: sources
      .filter((s) => s.id.startsWith('screen:'))
      .map((s) => ({ id: s.id, display_id: s.display_id, empty: s.thumbnail.isEmpty(), size: s.thumbnail.getSize() })),
  });

  results.push(await cap('after-immediate'));
  await new Promise((resolve) => setTimeout(resolve, 1500));
  results.push(await cap('after-delay'));

  console.log(JSON.stringify(results, null, 2));
  app.exit(0);
});
```

Observed output from one run:

```json
[
  { "media": "granted" },
  { "label": "before", "ok": true, "bytes": 6874575, "size": { "width": 2880, "height": 1800 } },
  {
    "screens": [
      { "id": "screen:1088685634:0", "display_id": "1088685634", "empty": false, "size": { "width": 1920, "height": 540 } },
      { "id": "screen:69734208:0", "display_id": "69734208", "empty": false, "size": { "width": 1728, "height": 1080 } },
      { "id": "screen:724857621:0", "display_id": "724857621", "empty": false, "size": { "width": 1920, "height": 1080 } }
    ]
  },
  {
    "label": "after-immediate",
    "ok": false,
    "message": "Command failed: /usr/sbin/screencapture -x -t png -D 1 /var/folders/.../electron-screencapture-31688-after-immediate.png\ncould not create image from display\n",
    "stderr": "could not create image from display\n"
  },
  { "label": "after-delay", "ok": true, "bytes": 6874505, "size": { "width": 2880, "height": 1800 } }
]
```

A separate app log also captured this failing in a real fallback path immediately after `desktopCapturer.getSources()` returned three screen sources where two external-display thumbnails were empty. The app workaround is retry/backoff and, for the primary display, retrying with `screencapture -m`.
